// Round half toward +Infinity at two decimals, working in decimal, not binary:
// toPrecision(15) drops float addition noise (0.03 + 0.005 is 0.034999999999999996),
// then the exponent shift avoids 1.005 * 100 landing below 100.5.
// Below 1e-6 the result is 0; from 1e13 up the value has no cents left to round.
const round2 = (x) => {
  if (!Number.isFinite(x) || Math.abs(x) >= 1e13) return x;
  if (Math.abs(x) < 1e-6) return 0;
  const clean = Number(x.toPrecision(15));
  return Math.round(Number(`${clean}e2`)) / 100 + 0;
};

export const sum = (a, b) => round2(Number(a) + Number(b));
EOF
